#include "runtime/interpreter.hpp"
#include <chrono>
#include <iostream>
namespace {int checks=0;void run(const std::string& source,const penta::runtime::ExecutionOptions& options,bool success=true){++checks;const auto result=penta::runtime::execute(source,{},options);if(result.ok()==success)return;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';throw std::runtime_error("Compiler pattern/DAE consistency fixture failed");}}
int main(int argc,char**argv){penta::runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-structural-dae-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(options.dataDirectory);options.odeCacheDirectory=options.dataDirectory/"kernels";if(argc>1)options.numericModuleDirectory=std::filesystem::absolute(argv[1]);try{
    run(R"(native function [real first,real second] objective(real x,real y,real weight){return weight*x*x,sin(y);}record pattern=jacobianpattern(objective);assert(pattern.rows==2&&pattern.columns==3&&pattern.nnz==3);record sparse_result=jacobiansparse(objective,[0,0],options(parameters=options(weight=2.0)));assert(sparse_result.columns==2&&sparse_result.nnz==2);assert(norm(sparse_result.values-[0,1])<1e-12);record changed=jacobiansparse(objective,[2,1],options(parameters=options(weight=3.0)));assert(changed.pattern_key==sparse_result.pattern_key);assert(changed.cache_key==sparse_result.cache_key);assert(changed.cache_hit);assert(abs(changed.values(1)-12)<1e-12);)",options);
    run(R"(native function real piecewise(real x,real y){if(x>0){return y;}return 0.0;}record sparse_result=jacobiansparse(piecewise,[-1,2]);assert(sparse_result.nnz==2);assert(sparse_result.includes_control_dependencies);assert(norm(sparse_result.values)==0);)",options);
    run(R"(native function real entry(matrix<2,2> values){return values(2,1);}record sparse_result=jacobiansparse(entry,[1,2;3,4]);assert(sparse_result.nnz==1);assert(sparse_result.column_indices(1)==3);assert(sparse_result.values(1)==1);)",options);
    run(R"(native function [real first,real second] residual(real t,real x,real z,real xp,real zp,real rate){return xp+rate*x,z^3-x*x-sin(t);}record structure=daestructure(residual,0.3,[1.2,1],[5,6],options(parameters=options(rate=2.0)));assert(structure.index_candidate==1&&structure.local_initialization_supported);record initial=daeinitialize(residual,0.3,[1.2,1],[5,6],options(parameters=options(rate=2.0),residual_tolerance=1e-12));real zz=(1.44+sin(0.3))^(1.0/3.0);assert(abs(initial.consistent_initial(2)-zz)<1e-10);assert(abs(initial.consistent_derivative(1)+2.4)<1e-11);assert(abs(initial.consistent_derivative(2)-(-5.76+cos(0.3))/(3*zz*zz))<1e-10);assert(initial.differentiated_residual_norm<1e-10);record changed=daeinitialize(residual,0.3,[1.2,1],[5,6],options(parameters=options(rate=3.0)));assert(changed.cache_hit&&changed.cache_key==initial.cache_key);)",options);
    run(R"(native function [real first,real second,real third] residual(real t,real x,real y,real z,real xp,real yp,real zp){return yp-x,zp-y,z-sin(t);}record structure=daestructure(residual,0.0,[0,0,0],[0,0,0]);assert(structure.index_candidate==3);assert(structure.maximum_equation_offset==2);assert(!structure.local_initialization_supported);)",options);
    run(R"(native function [real first,real second] residual(real t,real x,real z,real xp,real zp){return zp-x,z-sin(t);}record rejected=daeinitialize(residual,0.0,[0,0],[0,0]);)",options,false);
    run(R"(native function [real first,real second] residual(real t,real x,real z,real xp,real zp){return xp+x,z^3-x*x;}record rejected=daeinitialize(residual,0.0,[1,0],[0,0]);)",options,false);
    run(R"(native function real residual(real t,real y,real yp){return y-sin(t);}record initial=daeinitialize(residual,0.4,0.0,0.0);assert(abs(initial.consistent_initial(1)-sin(0.4))<1e-11);assert(abs(initial.consistent_derivative(1)-cos(0.4))<1e-11);)",options);
    run(R"(algebra H=builtin_algebra("quaternion");native function element<H> residual(real t,element<H> y,element<H> yp){return yp+y;}element point=H.i+2*H.j;record initial=daeinitialize(residual,0.0,point,0*H.i);assert(norm(initial.consistent_derivative+algebra_coefficients(point))<1e-11);record diagnostic=daeanalyze(residual,0.0,point,-point);assert(diagnostic.local_index==0);)",options);
    for(const auto command:{"daeanalyze","daestructure","daeinitialize"})run(std::string(R"(algebra H=builtin_algebra("quaternion");algebra S=builtin_algebra("split_quaternion");native function element<H> residual(real t,element<H> y,element<H> yp){return yp+y;}element wrong=S.i;record rejected=)")+command+"(residual,0.0,wrong,wrong);",options,false);
    run(R"(native function matrix<2,2> residual(real t,matrix<2,2> y,matrix<2,2> yp){return yp+y;}matrix<1,4> wrong=[1,2,3,4];record rejected=daeinitialize(residual,0.0,wrong,wrong);)",options,false);
    run(R"(native function tensor<2,1,1> residual(real t,tensor<2,1,1> y,tensor<2,1,1> yp){tensor<2,1,1> result=tensor(0.0,[2,1,1]);result(1)=yp(1)+y(1);result(2)=y(2)-y(1)*y(1);return result;}tensor<2,1,1> point=tensor([1,0],[2,1,1]);tensor<2,1,1> guess=tensor(0.0,[2,1,1]);record initial=daeinitialize(residual,0.0,point,guess);assert(initial.index_candidate==1);assert(norm(initial.consistent_initial-[1,1])<1e-11);assert(norm(initial.consistent_derivative-[-1,-2])<1e-11);record solved=daesolve(residual,initial.consistent_initial,initial.consistent_derivative,options(algebraic=initial.algebraic,t1=1,sample_step=0.05));assert(norm(solved.values(:,1)-exp(-solved.t))<1e-6);assert(norm(solved.values(:,2)-exp(-2*solved.t))<1e-6);)",options);
    run(R"(native function tensor<2,2,2> residual(real t,tensor<2,2,2> y,tensor<2,2,2> yp){return yp+y;}tensor<4,2> wrong=tensor(0.0,[4,2]);record rejected=daeinitialize(residual,0.0,wrong,wrong);)",options,false);
    run(R"(algebra H=builtin_algebra("quaternion");algebra S=builtin_algebra("split_quaternion");native function element<H> residual(real t,element<H> y,element<H> yp){return yp+y;}native function real wrong_event(real t,element<S> y,element<S> yp){return coeff(y,0);}record rejected=daesolve(residual,[1,0,0,0],[-1,0,0,0],options(algebraic=[0,0,0,0],event=wrong_event));)",options,false);
    std::cout<<"PASS "<<checks<<" compiler-pattern/structural DAE language checks\n";
}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);}
